unsigned aspace_destroy(uint64_t as) {
    if (as == kernel_pml4) return 0;
    if (as == current_as) aspace_switch(kernel_pml4);
    uint64_t *pml4 = (uint64_t *)(uintptr_t)as;
    unsigned n = 0;
    for (int i = 0; i < 512; i++)
        if (pml4[i] & PTE_P)
            n += free_tree(pml4[i] & ADDR_MASK, 2);
    frame_free(as);
    return n + 1;
}
